#pragma once

// java.util.concurrent.Future 模板接口桩。
// 表示一个异步计算的结果：可阻塞获取、可取消、可查询完成状态。
template<typename T>
class Future {
public:
    virtual ~Future() = default;

    // 阻塞等待并返回结果；任务异常完成或被取消时抛异常
    virtual T get() = 0;
    // 尝试取消任务；已完成或已取消时返回 false
    virtual bool cancel(bool mayInterruptIfRunning) = 0;
    // 任务是否已结束（正常完成、异常完成或被取消均视为 done）
    virtual bool isDone() = 0;
};
